const cfg = $input.first().json;
let base = String(cfg.siteBaseUrl || '');
while (base.endsWith('/')) base = base.slice(0, -1);
if (!base.startsWith('http://') && !base.startsWith('https://')) throw new Error('Config: siteBaseUrl must start with http:// or https://');
const brands = Array.isArray(cfg.brands) ? cfg.brands : [];
if (brands.length === 0) throw new Error('Config: brands is empty');
const day = $now.setZone('Europe/Bucharest').toFormat('yyyy-MM-dd');
const api = base + '/api/automation/social/v1';
return brands.map((b) => {
  const slug = String(b.slug || '');
  const eventId = 'news-' + slug + '-' + day;
  return {
    json: {
      brand: slug,
      event_id: eventId,
      url: api + '/generation-requests',
      runsUrl: api + '/runs',
      body: {
        workflow: 'news-to-drafts',
        event_id: eventId,
        brand: slug,
        input: {
          source: { type: 'news', topic: String(b.topic || ''), window_days: Number(b.window_days) || 7 },
          research: true,
          kinds: ['social'],
          count: Number(b.count) || 3,
          language: 'ro',
          templates: Array.isArray(b.templates) && b.templates.length > 0 ? b.templates : ['dark', 'light', 'mint'],
          platforms: b.platforms,
        },
      },
    },
  };
});

const sent = $('Build requests').all();
return $input.all().map((item, i) => {
  const req = sent[i].json;
  const r = item.json;
  const body = r.body && typeof r.body === 'object' ? r.body : {};
  let status = 'error';
  const details = { brand: req.brand };
  if (r.error !== undefined) {
    details.error = String(r.error.message || r.error).slice(0, 300);
  } else if (r.statusCode >= 200 && r.statusCode < 300) {
    status = 'ok';
    details.statusCode = r.statusCode;
    details.request_id = body.request_id;
    details.created = body.created;
    if (body.created === false) details.note = 'already existed (possibly created by a retried call)';
  } else {
    details.statusCode = r.statusCode;
    details.response = JSON.stringify(r.body === undefined ? null : r.body).slice(0, 300);
  }
  return { json: { url: req.runsUrl, body: { workflow: 'news-to-drafts', event_id: req.event_id, status, details } } };
});
